379					const key = headToken(text, ' (<:;=?');
380					if (key !== '' && text.includes(':')) {
381						const entry = members.get(open) ?? { returns: '', keys: new Set<string>() };
382						entry.keys.add(key);
383						members.set(open, entry);
384					}
385				}
386				if (open !== null && depth === 1 && text.endsWith(';')) {
387					const marker = text.lastIndexOf('): ');
388					const returns = marker < 0 ? '' : text.slice(marker + 3, text.length - 1).trim();
389					const entry = members.get(open) ?? { returns: '', keys: new Set<string>() };
390					if (entry.returns === '') entry.returns = returns;
391					members.set(open, entry);
392					open = null;
393				}
394			}
395		}
396		return Object.freeze({
397			package: packageName,
398			version,
399			symbol,
400			members: Object.freeze(
401				[...members.entries()]
402					.sort((left, right) => (left[0] < right[0] ? -1 : 1))
403					.map((entry) =>
404						Object.freeze({
405							member: entry[0],
406							returns: entry[1].returns,
407							optionKeys: Object.freeze([...entry[1].keys].sort()),
408						}),
409					),
410			),
411			complete,
412		});
413	}
