441	/**
442	 * The `TS2339` diagnostics an Angular build log states, per file, reduced to the
443	 * ones whose receiver the compiler named as an RxJS type.
444	 *
445	 * The filter is the honest part. A `TS2339` on a DOM interface is a different
446	 * capability's diagnostic and feeding it here would refuse the whole module for
447	 * a reason that is not about RxJS; the receiver type is the compiler's own
448	 * words, so the separation is read rather than guessed. Positions are the
449	 * compiler's, into the bytes it compiled — which is why the capability that
450	 * takes them re-places every one of them before it edits anything.
451	 */
452	export function readRxjsPatchDiagnostics(log: string): readonly RxjsPatchDiagnosticReading[] {
453		const byPath = new Map<string, PatchedCallDiagnostic[]>();
454		for (const line of log.split('\n')) {
455			const text = line.trim();
456			const marker = ' - error TS2339: Property ';
457			const at = text.indexOf(marker);
458			if (at < 0) continue;
459			const head = text.slice(0, at);
460			const tail = text.slice(at + marker.length);
461			const property = tail.split("'")[1];
462			const receiver = tail.split("on type '")[1]?.split("'")[0];
463			if (property === undefined || receiver === undefined) continue;
464			const bare = receiver.startsWith('typeof ') ? receiver.slice('typeof '.length) : receiver;
465			const head0 = bare.split('<')[0] ?? bare;
466			if (!RXJS_RECEIVER_TYPES.includes(head0)) continue;
467			const parts = head.replace('Error: ', '').split(':');
468			const column = Number(parts.at(-1));
469			const lineNumber = Number(parts.at(-2));
470			const file = parts.slice(0, -2).join(':').trim();
471			if (!Number.isInteger(column) || !Number.isInteger(lineNumber) || file === '') continue;
472			const list = byPath.get(file) ?? [];
473			list.push(
474				Object.freeze({ line: lineNumber, column, property, receiverType: receiver }),
475			);
476			byPath.set(file, list);
477		}
478		return Object.freeze(
479			[...byPath.entries()]
480				.sort((left, right) => (left[0] < right[0] ? -1 : 1))
481				.map((entry) => Object.freeze({ path: entry[0], diagnostics: Object.freeze(entry[1]) })),
482		);
483	}
