626		Object.freeze({
627			package: '@angular/common/http',
628			specifier: '@angular/http',
629			from: 'Http',
630			to: 'HttpClient',
631			arity: 1,
632			since: 'Angular 8 (the package stops at 7.2.16)',
633		}),
634		Object.freeze({
635			package: '@angular/common/http',
636			specifier: '@angular/http',
637			from: 'Response',
638			to: 'HttpResponse',
639			arity: 1,
640			since: 'Angular 8 (the package stops at 7.2.16)',
641		}),
642		Object.freeze({
643			package: '@angular/common/http',
644			specifier: '@angular/http',
645			from: 'Headers',
646			to: 'HttpHeaders',
647			arity: 1,
648			since: 'Angular 8 (the package stops at 7.2.16)',
649		}),
650		Object.freeze({
651			package: '@angular/common/http',
652			specifier: '@angular/http',
653			from: 'HttpModule',
654			to: 'HttpClientModule',
