660	/**
661	 * What the installed target closure answers for a successor that lives in a
662	 * *different* package from the specifier that went away.
663	 *
664	 * The reading the seam takes is keyed by the pair (`package`, `specifier`), and
665	 * nothing in its shape requires the two to belong to one package — so a
666	 * cross-package successor is readable, and this is the reading. `specifierResolves`
667	 * asks the closure whether `@angular/http` is still installed at all;
668	 * `rootExports` is the published surface of the entry point the claims name,
669	 * read from that entry point's own declaration file.
670	 */
671	export async function readCrossPackageRootSurface(
672		tree: string,
673		successorSpecifier: string,
674		removedSpecifier: string,
675	): Promise<RootSurfaceReading> {
676		const modules = path.join(tree, 'node_modules');
677		const owner = successorSpecifier.startsWith('@')
678			? successorSpecifier.split('/').slice(0, 2).join('/')
679			: (successorSpecifier.split('/')[0] ?? successorSpecifier);
680		let version = 'unknown';
681		try {
682			const manifest = JSON.parse(
683				await readFile(path.join(modules, owner, 'package.json'), 'utf8'),
684			) as Readonly<{ version?: unknown }>;
685			if (typeof manifest.version === 'string') version = manifest.version;
686		} catch {
687			version = 'unknown';
688		}
689		const declaration = path.join(modules, successorSpecifier, 'index.d.ts');
690		const names = new Set<string>();
691		if (existsSync(declaration)) {
692			const source = await readFile(declaration, 'utf8');
693			for (const line of source.split('\n')) {
694				const match = /^export\s+declare\s+(?:abstract\s+)?(?:class|function|const|enum)\s+([A-Za-z0-9_$]+)/.exec(
695					line,
696				);
697				if (match?.[1] !== undefined) names.add(match[1]);
698				const type = /^export\s+(?:declare\s+)?(?:type|interface)\s+([A-Za-z0-9_$]+)/.exec(line);
699				if (type?.[1] !== undefined) names.add(type[1]);
700				const named = /^export\s*\{([^}]*)\}/.exec(line);
701				if (named?.[1] !== undefined)
702					for (const part of named[1].split(','))
703						names.add((part.split(/\s+as\s+/).at(-1) ?? part).trim());
704			}
705			names.delete('');
706		}
707		return Object.freeze({
708			package: successorSpecifier,
709			version,
710			specifier: removedSpecifier,
711			specifierResolves: existsSync(path.join(modules, '@angular/http')),
712			rootExports: Object.freeze([...names].sort()),
713			complete: names.size > 0,
714		});
715	}
