880	 * has read this application on the target line is the one the previous pass ran.
881	 * Reading its log is what makes those positions available to this pass; that
882	 * they are positions in bytes a previous composition produced is exactly why the
883	 * capability that takes them re-places every one before it edits anything.
884	 */
885	export const PRIOR_BUILD_LOG = path.join(EVIDENCE_DIRECTORY, 'u1-t024-target-build.log');
886	
887	export async function main(): Promise<void> {
888		const log = existsSync(PRIOR_BUILD_LOG) ? await readFile(PRIOR_BUILD_LOG, 'utf8') : null;
889		const readings = await readLaneReadings(APPLIED_TREE, log);
890		const migration = await composeMigration(SOURCE_TREE, readings);
891		const changeset = verifySealedRecord(buildChangesetRecord(migration));
892		const applied = await applyMigration(migration, APPLIED_TREE);
893		const record = verifySealedRecord(buildApplicationRecord(migration, applied));
894		const surfaceTree = existsSync(path.join(APPLIED_TREE, 'node_modules'))
895			? APPLIED_TREE
896			: SURFACE_PROBE_TREE;
897		const reading = await readCrossPackageRootSurface(
898			surfaceTree,
899			'@angular/common/http',
900			'@angular/http',
901		);
902		const outcomes = driveAngularHttpSeam(migration, reading);
903		const probe = verifySealedRecord(buildSeamProbeRecord(reading, outcomes, surfaceTree));
904		await mkdir(EVIDENCE_DIRECTORY, { recursive: true });
905		await writeFile(path.join(EVIDENCE_DIRECTORY, CHANGESET_FILE), canonical(changeset));
906		await writeFile(path.join(EVIDENCE_DIRECTORY, MIGRATION_RECORD_FILE), canonical(record));
907		await writeFile(path.join(EVIDENCE_DIRECTORY, SEAM_PROBE_FILE), canonical(probe));
908		process.stdout.write(
909			`applied ${String(applied.written.length)} files (${String(
910				migration.applicationFilesChanged,
911			)}/${String(migration.applicationFilesScanned)} application, ${String(
912				migration.workspaceFilesChanged,
913			)} workspace), removed ${String(applied.removed.length)}, ` +
914				`${String(migration.unhandled.length)} unhandled, ${String(
915					migration.declaredDifferences.length,
916				)} declared differences; seam offered ${String(outcomes.length)} module(s), changed ` +
917				`${String(outcomes.filter((entry) => entry.changed).length)}; changeset digest ${sha256(
918					canonical(changeset),
919				).slice(0, 12)}\n`,
920		);
921	}
922	
923	if (process.argv[1]?.endsWith('angular-eshop-webspa-migration-run.ts'))
924		main().catch((error: unknown) => {
925			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
926			process.exitCode = 1;
927		});
